package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtRec AmtRec

var inputLines []string
var inputIdx int

func main() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		inputLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			line := sc.Text()
			// Scanner strips newline, keeps content without \r
			// Remove possible \r (for Windows line endings)
			line = strings.TrimSuffix(line, "\r")
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0

	performReadPara()
	for WsEofFlag != "Y" {
		performProcessPara()
	}
	// CLOSE AMT-FILE (no action)
	performSummaryPara()
}

// READ-PARA.
func performReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	raw := inputLines[inputIdx]
	inputIdx++
	// pad with spaces on right to record length 11
	if len(raw) < 11 {
		raw = raw + strings.Repeat(" ", 11-len(raw))
	} else if len(raw) > 11 {
		raw = raw[:11]
	}
	amtRec.ArAcct = raw[0:4]
	s := raw[4:11] // 7 bytes
	// parse digits: PIC 9(5)V99 -> scale 2
	// COBOL numeric display: digits only, implied decimal
	// If line was padded with spaces, s may contain spaces; treat spaces as 0?
	// Remove spaces then parse, if empty => 0
	trimmed := strings.TrimSpace(s)
	var digitsOnly string
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digitsOnly += string(ch)
		}
	}
	if digitsOnly == "" {
		if trimmed == "" {
			amtRec.ArAmt = decimal.NewFromInt(0)
		} else {
			amtRec.ArAmt = decimal.NewFromInt(0)
		}
	} else {
		// digitsOnly should be up to 7 digits, but may be shorter if spaces were trimmed
		// To keep scale correctly, we need to treat digitsOnly as the scaled integer.
		// However if the field contained spaces due to padding, the original field would be
		// spaces, not zeros. We treat as zero.
		// For normal records digitsOnly length ==7.
		// Build decimal with scale 2: value = int(digitsOnly) *10^-2
		// If digitsOnly length <7 due to leading zeros omitted? No, COBOL writes full width with zeros.
		// So just parse as integer.
		// Pad left with zeros to 7 if needed? Actually if digitsOnly shorter but represents same scaled value
		// with leading zeros omitted, parsing as integer still gives correct value because leading zeros don't affect integer.
		// So we can directly parse.
		bi, _ := decimal.NewFromString(digitsOnly)
		amtRec.ArAmt = decimal.New(bi.IntPart(), -2)
	}
}

// helper to store with truncation (low-order digits)
func storeTruncate(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	modPow := intDigits + scale
	// modulus = 10^(intDigits+scale)
	mod := decimal.New(1, int32(modPow))
	// scaled = val * 10^scale
	factor := decimal.New(1, int32(scale))
	scaled := val.Mul(factor)
	// scaled should be integer (with possible fractional due to representation, truncate towards zero to integer)
	scaled = scaled.Truncate(0)
	// mod operation keeping sign (val is non-negative here)
	// Use decimal Mod? For positive numbers we can do IntPart mod.
	// Use big int via IntPart if fits in int64, else use decimal remainder.
	// Values are small, use IntPart.
	// But to be safe for larger values use decimal Mod via: scaled.Mod(mod)
	// shopspring decimal Mod works for positive.
	// Ensure truncatedScaled is positive remainder
	// For negative (not needed) would need handling.
	rem := scaled.Mod(mod)
	// Mod may return negative for negative, not needed.
	if rem.IsNegative() {
		rem = rem.Add(mod)
	}
	return rem.Div(factor)
}

func fitsInPic(val decimal.Decimal, intDigits int, scale int) bool {
	// max = 10^n - 10^-scale  e.g., 9(5)V99 => 99999.99
	// Equivalent to scaled max = 10^(n+scale)-1
	if val.IsNegative() {
		return false
	}
	factor := decimal.New(1, int32(scale))
	scaled := val.Mul(factor).Truncate(0)
	// need scaled <= 10^(n+scale)-1
	maxScaled := decimal.New(1, int32(intDigits+scale)).Sub(decimal.NewFromInt(1))
	// also need that val has no more fractional digits than scale? For ADD case val has scale 2 exactly, so fine.
	return scaled.Cmp(maxScaled) <= 0
}

func formatEdited(val decimal.Decimal, pattern string) string {
	// pattern like "ZZ,ZZ9.99" or "ZZ,ZZ9.9"
	dotIdx := strings.Index(pattern, ".")
	var intPat, decPat string
	if dotIdx >= 0 {
		intPat = pattern[:dotIdx]
		decPat = pattern[dotIdx+1:]
	} else {
		intPat = pattern
		decPat = ""
	}
	decPlaces := len(decPat)

	// Ensure val is non-negative, truncated to decPlaces scale?
	// Value passed is already at appropriate scale, but we format fractional exactly decPlaces digits.
	// Compute scaled integer for fractional part: val *10^decPlaces truncated
	factor := decimal.New(1, int32(decPlaces))
	scaled := val.Mul(factor).Truncate(0)
	// For negative (not needed) handle sign
	isNeg := scaled.IsNegative()
	if isNeg {
		scaled = scaled.Neg()
	}
	// integer part
	intPartScaled := scaled.Div(decimal.New(1, int32(decPlaces))).Truncate(0)
	fracPartScaled := scaled.Mod(decimal.New(1, int32(decPlaces)))
	// But Mod with decimal may be fractional; better use integer arithmetic via IntPart
	// Use IntPart for small numbers
	intPartInt := intPartScaled.IntPart()
	fracInt := fracPartScaled.IntPart()
	if fracInt < 0 {
		fracInt = -fracInt
	}

	intDigitsStr := fmt.Sprintf("%d", intPartInt)
	// count placeholders in intPat
	placeCount := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			placeCount++
		}
	}
	// keep low-order digits if overflow
	if len(intDigitsStr) > placeCount {
		intDigitsStr = intDigitsStr[len(intDigitsStr)-placeCount:]
	}
	// Build filled integer part
	// Fill digit placeholders from rightmost
	filled := []rune(intPat)
	// Need digit pointer
	dIdx := len(intDigitsStr) - 1
	for i := len(intPat) - 1; i >= 0; i-- {
		if intPat[i] == 'Z' || intPat[i] == '9' {
			var ch rune
			if dIdx >= 0 {
				ch = rune(intDigitsStr[dIdx])
				dIdx--
			} else {
				ch = '0'
			}
			filled[i] = ch
		} else {
			// comma stays as comma for now
			filled[i] = rune(intPat[i])
		}
	}
	// Determine first non-zero placeholder index in terms of placeholder order
	// Build list of placeholder positions
	type posInfo struct {
		idx int
		ch  rune
	}
	var placeholders []posInfo
	for i, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			placeholders = append(placeholders, posInfo{i, filled[i]})
		}
	}
	firstNonZero := -1
	for i, p := range placeholders {
		if p.ch != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zeros => position of last placeholder (the '9')
		firstNonZero = len(placeholders) - 1
	}
	// Apply suppression
	for i, p := range placeholders {
		patCh := rune(intPat[p.idx])
		if patCh == 'Z' && i < firstNonZero {
			filled[p.idx] = ' '
		} else {
			// keep digit
			filled[p.idx] = p.ch
		}
	}
	// Commas: if still in suppressed zone, turn to space
	// Suppressed zone is before firstNonZero placeholder's pattern index.
	// Any comma that lies before the pattern index of placeholders[firstNonZero] is suppressed.
	suppressLimit := -1
	if len(placeholders) > 0 && firstNonZero < len(placeholders) {
		suppressLimit = placeholders[firstNonZero].idx
	}
	for i, ch := range intPat {
		if ch == ',' {
			if suppressLimit != -1 && i < suppressLimit {
				filled[i] = ' '
			} else {
				// need to check if all placeholders before this comma were suppressed?
				// Our suppressLimit already handles. Keep comma otherwise.
				filled[i] = ','
			}
		}
	}
	intResult := string(filled)
	if decPlaces > 0 {
		fracStr := fmt.Sprintf("%0*d", decPlaces, fracInt)
		return intResult + "." + fracStr
	}
	return intResult
}

// PROCESS-PARA.
func performProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	sumBig := WsBigTotal.Add(amtRec.ArAmt)
	WsBigTotal = storeTruncate(sumBig, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeTruncate(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	sumSafe := WsSafeTotal.Add(amtRec.ArAmt)
	if fitsInPic(sumSafe, 5, 2) {
		WsSafeTotal = sumSafe
	} else {
		performOverflowPara()
	}

	// ADD 1 TO WS-COUNT
	WsCount++
	// COBOL PIC 99 overflow truncates high digits (mod 100)
	if WsCount > 99 {
		WsCount = WsCount % 100
	}

	// COMPUTE WS-HALF = AR-AMT / 2   (truncated)
	// Use decimal division
	halfRaw := amtRec.ArAmt.Div(decimal.NewFromInt(2))
	// Truncate to scale 1
	halfTrunc := halfRaw.Truncate(1)
	WsHalf = storeTruncate(halfTrunc, 5, 1)

	WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	// DISPLAY
	// AR-ACCT is PIC X(4) exact
	fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	performReadPara()
}

// SUMMARY-PARA.
func performSummaryPara() {
	// DISPLAY "RECORDS: " WS-COUNT  -> PIC 99 zero padded 2
	recStr := fmt.Sprintf("%02d", WsCount)
	ovStr := fmt.Sprintf("%02d", WsOverflows)
	fmt.Printf("RECORDS: %s\n", recStr)
	fmt.Printf("OVERFLOWS: %s\n", ovStr)
}

// OVERFLOW-PARA.
func performOverflowPara() {
	WsOverflows++
	if WsOverflows > 99 {
		WsOverflows = WsOverflows % 100
	}
}
